with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

task_examples = {}
for d in demos:
    tid = d.get('task_id')
    if tid not in task_examples:
        inp = d.get('input_examples', [])[:5]
        out = d.get('output_examples', [])[:5]
        task_examples[tid] = (inp, out)

# Analyze each task pattern
for tid in sorted(task_examples.keys(), key=lambda x: int(x[1:])):
    inp, out = task_examples[tid]
    print(f"\n{'='*60}")
    print(f"Task {tid}:")
    for j in range(min(4, len(inp))):
        i = inp[j]
        o = out[j]
        print(f"  Input len={len(i)}, Output len={len(o)}: {i} -> {o}")
        # Quick analysis
        if len(i) == 0:
            print(f"    (empty input)")
        elif len(o) == len(i):
            print(f"    (same length)")
            # check if sorted
            if sorted(i) == o:
                print(f"    -> SORTED")
            if i == o:
                print(f"    -> IDENTITY (first element special?)")
            # check for specific transforms
            if all(o[k] == min(i) if k == 0 else i[k] for k in range(len(i))):
                print(f"    -> first replaced with min")
        elif len(o) == 1:
            # Single element - what is it?
            if o[0] == len(i):
                print(f"    -> count = len(input)")
            elif o[0] == min(i):
                print(f"    -> min")
            elif o[0] == max(i):
                print(f"    -> max")
            elif o[0] == sum(i):
                print(f"    -> sum")
            else:
                print(f"    -> single element: {o[0]}")
        elif len(o) > len(i):
            if o[:len(i)] == i:
                print(f"    -> input prefix + extra")
            elif i[0] in o:
                print(f"    -> input[0] appears in output")

