for d in demos:
    if d.get('task_id') == 'c118':
        inp = d.get('input_examples', [])
        out = d.get('output_examples', [])
        print(f"Task c118: {len(inp)} examples")
        for i, (ix, ox) in enumerate(zip(inp, out)):
            # Check all rotations
            n = len(ix)
            match_k = []
            for k in range(n + 1):
                kk = k % n
                if kk == 0:
                    r = list(ix)
                else:
                    r = ix[-kk:] + ix[:-kk]
                if r == ox:
                    match_k.append(f"rotR{k}")
            left_k = []
            for k in range(n + 1):
                if k == 0:
                    r = list(ix)
                else:
                    r = ix[k:] + ix[:k]
                if r == ox:
                    left_k.append(f"rotL{k}")
            print(f"  {ix} -> {ox}")
            print(f"    Right matches: {match_k}")
            print(f"    Left matches: {left_k}")
        break

